import Image from "next/image";
import { cn } from "@/lib/utils";

// Pixel sizes of the files in public/marketing (generated by .claude/tools/marketing-shots.mjs).
const SHOTS = {
  "hero-desktop": [1440, 900],
  "hero-phone": [420, 933],
  "tasks-board": [1100, 617],
  "tasks-list": [560, 870],
  ideas: [1100, 234],
  learn: [1100, 412],
  money: [1100, 552],
} as const;

export type ShotName = keyof typeof SHOTS;

/** A product screenshot with a dark and a light file; CSS (the `.light` class on <html>) picks one. */
export function Shot({
  name,
  alt,
  sizes,
  priority,
  className,
}: {
  name: ShotName;
  alt: string;
  sizes: string;
  priority?: boolean;
  className?: string;
}) {
  const [width, height] = SHOTS[name];
  const base = cn("h-auto w-full", className);
  return (
    <>
      <Image
        src={`/marketing/${name}-dark.webp`}
        alt={alt}
        width={width}
        height={height}
        sizes={sizes}
        priority={priority}
        className={cn(base, "[.light_&]:hidden")}
      />
      <Image
        src={`/marketing/${name}-light.webp`}
        alt={alt}
        width={width}
        height={height}
        sizes={sizes}
        fetchPriority={priority ? "high" : undefined}
        className={cn(base, "hidden [.light_&]:block")}
      />
    </>
  );
}

/** Window chrome around a desktop screenshot. */
export function Frame({
  children,
  className,
  chrome = true,
}: {
  children: React.ReactNode;
  className?: string;
  chrome?: boolean;
}) {
  return (
    <div
      className={cn(
        "overflow-hidden rounded-xl border border-border bg-surface shadow-lg",
        className,
      )}
    >
      {chrome && (
        <div className="flex items-center gap-1.5 border-b border-border bg-surface-2 px-3 py-2.5" aria-hidden>
          <span className="h-2.5 w-2.5 rounded-full bg-border" />
          <span className="h-2.5 w-2.5 rounded-full bg-border" />
          <span className="h-2.5 w-2.5 rounded-full bg-border" />
        </div>
      )}
      {children}
    </div>
  );
}

/** Rounded phone bezel around a phone screenshot. */
export function PhoneFrame({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <div
      className={cn(
        "overflow-hidden rounded-xl border-4 border-border bg-surface shadow-lg",
        className,
      )}
    >
      {children}
    </div>
  );
}
